import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const appRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const threePath = join(appRoot, 'node_modules', 'three', 'build', 'three.module.js');
const outputPath = join(appRoot, 'src', 'three-source.ts');

const source = (await readFile(threePath, 'utf8')).replace(
  /\n?\/\/# sourceMappingURL=.*$/m,
  '',
);

await writeFile(
  outputPath,
  `// Generated by scripts/embed-three.mjs. Do not edit.\nexport const THREE_SOURCE = ${JSON.stringify(source)};\n`,
);
